    // "a · b · c": translate each part on its own (e.g. "Client · Oct 8, 2:16 AM").
    if (v === null && k.includes(' · ')) { const parts = k.split(' · '); const t = parts.map(p => tr(p)); if (t.some((x, i) => x !== parts[i])) v = t.join(' · '); }
    cache.set(k, v);
    return v === null ? str : str.replace(k, v);
